"""Preserve the exact original 50 questions and splits; curate sourced guidance separately."""
import json,csv,hashlib,sys,re,os
from pathlib import Path
from datetime import date
from docx import Document
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from app.engine import LABELS
(ROOT/'reports').mkdir(exist_ok=True);(ROOT/'data').mkdir(exist_ok=True)
source=next((ROOT/'sources').glob('*.docx'))
d=Document(source)
samples=[]
for table in d.tables:
    rows=[[cell.text.strip() for cell in row.cells] for row in table.rows]
    for cells in rows:
        if len(cells)==4 and cells[0].isdigit() and cells[2] in LABELS and cells[3] in ('Train','Validation','Test'):
            samples.append({'id':f'Q{int(cells[0]):03}','question':cells[1],'intent':cells[2],'split':cells[3],'group_id':f'Q{int(cells[0]):03}'})
unique={s['id']:s for s in samples};samples=sorted(unique.values(),key=lambda x:x['id'])
assert len(samples)==50, f'Expected exactly 50 original samples, found {len(samples)}'
assert {s:sum(r['split']==s for r in samples) for s in ('Train','Validation','Test')}=={'Train':30,'Validation':10,'Test':10}
with (ROOT/'data'/'original_50.csv').open('w',encoding='utf-8',newline='') as f:
    w=csv.DictWriter(f,fieldnames=list(samples[0]));w.writeheader();w.writerows(samples)
articles=json.loads((ROOT/'data'/'article_sources.json').read_text())
dorm=json.loads((ROOT/'data'/'dorm_sources.json').read_text())
sources={}
for item in articles+dorm:
    if item.get('text') and not item.get('error'):sources[item['url'].rstrip('/').split('/')[-1]]=item
def src(id,fallback=None):
    if id in sources:return sources[id]
    if fallback:return fallback
    raise ValueError('Missing verified source '+id)
sch=src('68191');fee=src('68147')
training={'url':'https://www.haui.edu.vn/vn/html/ban-dao-tao','title':'Ban Đào tạo — Đại học Công nghiệp Hà Nội'}
student={'url':'https://dsa.haui.edu.vn/vn','title':'Phòng Công tác học sinh sinh viên — HaUI'}
center={'url':'https://ssc.haui.edu.vn/vn','title':'Trung tâm Hỗ trợ sinh viên — HaUI'}
housing=src('69582',center);housing_dates=src('69584',center);housing_price=src('69583',center)
faqs=[]
def add(intent,q,answer,source,aliases='',kind='guidance',valid=None):
    id='FAQ-'+str(len(faqs)+1).zfill(3)
    faqs.append({'id':id,'question':q,'answer':answer,'intent':intent,'aliases':aliases,'source_url':source['url'],'source_title':source['title'].lstrip('» ').split(' (')[0],'reviewed_at':date.today().isoformat(),'valid_until':valid,'status':'approved','kind':kind})
add('hoc_phi','Quy định học phí năm học 2026–2027 ở đâu?','HaUI đã đăng Quyết định ban hành mức thu học phí đối với các chương trình đào tạo năm học 2026–2027. Bạn mở văn bản chính thức trong nguồn bên dưới và đối chiếu đúng chương trình, hệ đào tạo và khóa học. Mình chưa có dữ liệu để tính khoản học phí cá nhân của bạn. Bạn đang học chương trình nào?',fee,'mức thu đơn giá tín chỉ học phí bao nhiêu tiền một tín chỉ giá tiền chính quy cao học',valid='2027-08-31')
add('hoc_phi','Làm sao xem công nợ và số tiền học phí phải nộp?','Để biết số tiền học phí hoặc công nợ của riêng bạn, cần tra cứu tài khoản sinh viên trên hệ thống chính thức của trường. Mình chưa kết nối dữ liệu tài khoản và không thể xác nhận số tiền bạn phải nộp. Bạn có thể đi từ website HaUI đến hệ thống đào tạo; nếu thông tin chưa rõ, liên hệ Ban Đào tạo để được hướng dẫn đến đơn vị phụ trách.',training,'xem số tiền học phí khoản phải nộp tổng học phí công nợ tài khoản học kỳ')
add('hoc_phi','Hạn nộp học phí của học kỳ này là khi nào?','Mình chưa có thông báo đã đối chiếu về hạn nộp học phí cho học kỳ và khóa học của bạn. Bạn cho biết học kỳ, năm học và hệ đào tạo, đồng thời kiểm tra thông báo trên hệ thống chính thức của trường. Không nên dùng thời hạn của năm học khác để quyết định việc nộp tiền.',training,'đóng học phí muộn hạn đóng hạn nộp gia hạn chậm nộp ngày nào thời hạn')
add('hoc_phi','Đã chuyển khoản học phí nhưng chưa cập nhật thì làm gì?','Mình không thể kiểm tra giao dịch hoặc xác nhận học phí đã được ghi nhận. Bạn nên chuẩn bị chứng từ chuyển khoản và đối chiếu thông tin trên hệ thống chính thức; nếu vẫn chưa khớp, liên hệ đơn vị thu học phí qua kênh nhà trường. Không gửi ảnh có đầy đủ số tài khoản hoặc thông tin nhạy cảm trong cuộc trò chuyện.',training,'chuyển tiền đóng tiền chưa ghi nhận thanh toán hình thức nộp học phí chuyển khoản')
add('hoc_phi','Tìm chính sách miễn giảm học phí và hỗ trợ tài chính ở đâu?','Trang “Hỗ trợ tài chính và học bổng dành cho sinh viên HaUI” tổng hợp các chính sách hỗ trợ và nêu căn cứ áp dụng. Bạn cần đối chiếu đúng nhóm đối tượng, hồ sơ và thông báo hiện hành. Việc được hưởng chính sách phải do đơn vị phụ trách xác nhận; mình không tự kết luận từ thông tin chưa đầy đủ.',sch,'miễn giảm học phí hộ nghèo cận nghèo dân tộc hỗ trợ chi phí học tập chính sách')
add('dang_ky_hoc_phan','Làm thế nào để đăng ký học phần?','Bạn cần xem kế hoạch đăng ký học phần đúng học kỳ và hệ đào tạo trên hệ thống chính thức của HaUI. Mình chưa có lịch mở đăng ký hoặc quyền thao tác tài khoản của bạn. Bạn có thể vào trang Ban Đào tạo để tìm thông báo và kênh hỗ trợ; cho mình biết học kỳ, khóa học và vấn đề gặp phải để hướng dẫn tra cứu rõ hơn.',training,'đăng ký môn học đăng ký lớp học phần đăng ký bổ sung đkhp lịch mở đăng ký')
add('dang_ky_hoc_phan','Có thể hủy hoặc thay đổi lớp học phần đã đăng ký không?','Việc hủy hoặc thay đổi lớp học phần cần đối chiếu thời gian điều chỉnh và quy định áp dụng cho chương trình của bạn. Mình chưa có thông báo hiện hành để xác nhận bạn có được thay đổi hay không. Bạn nên kiểm tra kế hoạch của học kỳ và hỏi Ban Đào tạo hoặc cố vấn học tập trước khi thao tác.',training,'hủy môn đổi lớp thay đổi lớp rút học phần đã đăng ký')
add('dang_ky_hoc_phan','Lớp học phần đầy hoặc vướng môn tiên quyết thì xử lý thế nào?','Bạn cần xác định vấn đề là lớp đã đủ sĩ số, trùng lịch hay chưa đáp ứng học phần tiên quyết. Mình không thể mở lớp hoặc bỏ qua điều kiện đăng ký. Bạn hãy kiểm tra thông báo hiện hành và trao đổi với Ban Đào tạo/cố vấn học tập qua kênh chính thức để được xử lý theo trường hợp cụ thể.',training,'lớp đầy sĩ số hết chỗ không đăng ký được học lại môn tiên quyết')
add('dang_ky_hoc_phan','Xem thời khóa biểu và kiểm tra đăng ký học phần thành công ở đâu?','Bạn cần đăng nhập hệ thống đào tạo chính thức của trường để kiểm tra danh sách học phần và thời khóa biểu cá nhân. Mình chưa kết nối tài khoản sinh viên nên không thể xác nhận đăng ký đã thành công. Nếu kết quả không như mong đợi, bạn liên hệ Ban Đào tạo qua kênh chính thức.',training,'thời khóa biểu lịch học danh sách môn đăng ký thành công không truy cập được cổng')
add('lich_thi','Làm sao tra cứu lịch thi, ca thi và phòng thi?','Lịch thi cá nhân phải được kiểm tra trên hệ thống đào tạo hoặc thông báo chính thức đúng học kỳ. Mình chưa có dữ liệu lịch thi của từng sinh viên nên không thể cung cấp ngày, ca hay phòng thi cụ thể. Bạn cho biết học kỳ và học phần cần tra cứu, đồng thời theo dõi kênh Ban Đào tạo của trường.',training,'lịch thi cuối kỳ giữa kỳ ngày thi giờ thi ca thi địa điểm thi phòng thi')
add('lich_thi','Nếu lịch thi bị trùng hoặc có thay đổi thì liên hệ ai?','Bạn nên đối chiếu thông báo lịch thi mới nhất và báo vấn đề qua kênh Ban Đào tạo/đơn vị tổ chức thi của trường. Chuẩn bị tên học phần và thông tin ca thi bị vướng khi liên hệ trực tiếp. Mình chưa thể xác nhận việc đổi lịch hay quyết định phương án thi thay thế.',training,'trùng lịch thi lịch thi sai đổi lịch thi hoãn thi điều chỉnh lịch thi thông báo')
add('hoc_bong','HaUI có những loại học bổng và hỗ trợ tài chính nào?','Theo bài tổng hợp chính thức của HaUI ngày 11/09/2026, các nhóm gồm học bổng HaUI, học bổng khuyến khích học tập, học bổng cho sinh viên có định hướng học tiếp thạc sĩ, học bổng ngành kỹ thuật then chốt và công nghệ chiến lược, học bổng Nguyễn Thanh Bình và học bổng tài trợ. Mỗi loại có đối tượng, điều kiện và mức hỗ trợ riêng; bạn muốn tìm hiểu loại nào?',sch,'các loại học bổng học bổng sinh viên năm nhất danh sách thông báo học bổng hỗ trợ tài chính',kind='policy',valid='2027-08-31')
add('hoc_bong','Điều kiện duy trì học bổng HaUI là gì?','Theo bài tổng hợp HaUI ngày 11/09/2026, điều kiện duy trì học bổng HaUI gồm điểm trung bình chung học kỳ từ 2,5 và rèn luyện loại tốt trở lên; tổng số tín chỉ xét học bổng lớn hơn 15, trừ trường hợp kế hoạch của Đại học bố trí không đủ. Học kỳ cuối theo thời gian thiết kế khóa học yêu cầu lớn hơn 7 tín chỉ. Đây là điều kiện duy trì học bổng HaUI, không phải điều kiện chung cho mọi học bổng. Bạn cần xem đầy đủ căn cứ và trường hợp áp dụng trong nguồn.',sch,'duy trì học bổng HaUI 2.5 tín chỉ học kỳ cuối điều kiện giữ học bổng',kind='policy',valid='2027-08-31')
add('hoc_bong','Điều kiện xét học bổng khuyến khích học tập được công bố ở đâu?','Trang tổng hợp chính thức ngày 11/09/2026 nêu học bổng khuyến khích học tập dành cho sinh viên hệ đại học và cao đẳng chính quy, với xếp loại căn cứ kết quả học tập và rèn luyện. Bạn mở phần “Học bổng khuyến khích học tập” trong nguồn để đối chiếu đúng thang điểm và xếp loại. Mình chưa đủ thông tin để kết luận cá nhân bạn có được nhận học bổng hay không.',sch,'điều kiện học bổng khuyến khích xét học bổng điểm trung bình bao nhiêu rèn luyện quy trình',kind='policy',valid='2027-08-31')
add('hoc_bong','Hồ sơ, hạn nộp và kết quả xét học bổng xem ở đâu?','Hồ sơ, thời hạn và kết quả cần xem theo thông báo của từng chương trình học bổng. Mình chưa có thông báo tiếp nhận hồ sơ cụ thể cho trường hợp của bạn. Bài tổng hợp chính thức có phần thông tin liên hệ để được tư vấn. Bạn đang quan tâm học bổng nào và năm học nào?',sch,'giấy tờ học bổng hồ sơ hạn nộp thiếu giấy tờ nơi nộp tiếp nhận kết quả xét học bổng liên hệ')
add('hoc_bong','Học bổng Nguyễn Thanh Bình dành cho đối tượng nào?','Theo bài tổng hợp chính thức của HaUI, học bổng Nguyễn Thanh Bình hướng đến sinh viên có hoàn cảnh khó khăn, thành tích học tập hoặc nghiên cứu khoa học nổi bật và các trường hợp được liệt kê trong quy định. Mức học bổng cơ sở được xác định hằng năm. Bạn nên đọc đầy đủ danh sách đối tượng và hỏi đơn vị phụ trách để đối chiếu hồ sơ; không thể suy ra chắc chắn quyền lợi chỉ từ một điều kiện.',sch,'quỹ khuyến học Nguyễn Thanh Bình hộ nghèo bệnh hiểm nghèo hoàn cảnh khó khăn',kind='policy',valid='2027-08-31')
add('diem_hoc_tap','Xem điểm học phần và điểm trung bình học kỳ ở đâu?','Bạn cần đăng nhập hệ thống đào tạo chính thức của HaUI để xem điểm học phần, điểm trung bình học kỳ và kết quả học tập cá nhân. Mình chưa có quyền truy cập bảng điểm của bạn. Không gửi mật khẩu hoặc mã OTP; nếu không tìm được thông tin, liên hệ Ban Đào tạo qua kênh chính thức.',training,'xem điểm tra cứu điểm điểm tổng kết trung bình học kỳ gpa điểm từng môn chuyên cần kết quả thi cuối kỳ')
add('diem_hoc_tap','Điểm hiển thị sai hoặc cần phúc khảo thì làm gì?','Bạn nên đối chiếu điểm đã công bố và thông báo phúc khảo/điều chỉnh điểm của học kỳ, rồi liên hệ đơn vị phụ trách qua kênh Ban Đào tạo. Mình chưa có văn bản hiện hành để xác nhận hạn nộp, lệ phí hay kết quả điều chỉnh. Không nên dùng thời hạn của khóa hoặc kỳ khác.',training,'điểm sai điều chỉnh điểm phúc khảo khiếu nại điểm kết quả học tập không đúng')
add('diem_hoc_tap','Làm sao xem bảng điểm tích lũy hoặc kết quả học kỳ trước?','Bảng điểm tích lũy và kết quả học kỳ trước là dữ liệu cá nhân cần tra cứu trong tài khoản sinh viên trên hệ thống chính thức. Mình chưa kết nối dữ liệu này. Nếu cần bảng điểm có xác nhận, hãy hỏi Ban Đào tạo về thủ tục hiện hành.',training,'bảng điểm tích lũy học kỳ trước điểm toàn khóa kết quả học tập bảng điểm có xác nhận')
add('cong_tac_sinh_vien','Xin giấy xác nhận sinh viên để làm thủ tục như thế nào?','Bạn cần giấy xác nhận để làm thủ tục nào, chẳng hạn vay vốn hay tạm hoãn nghĩa vụ quân sự? Mỗi mục đích có thể cần biểu mẫu và hồ sơ khác nhau. Mình chưa có hướng dẫn hiện hành đã đối chiếu cho từng loại giấy; bạn liên hệ đơn vị công tác sinh viên của HaUI qua nguồn chính thức bên dưới để xác nhận thủ tục.',student,'giấy xác nhận sinh viên vay vốn nghĩa vụ quân sự xác nhận đang học giấy chứng nhận')
add('cong_tac_sinh_vien','Cần hỗ trợ thẻ sinh viên, bảo hiểm hoặc điểm rèn luyện thì tìm ở đâu?','Bạn có thể xem kênh thông tin công tác học sinh sinh viên của HaUI và tìm thông báo đúng nội dung: thẻ sinh viên, bảo hiểm hoặc điểm rèn luyện. Mình chưa có thông báo cụ thể để khẳng định hồ sơ, mức phí hoặc thời hạn của bạn. Bạn cho biết đang vướng thủ tục nào để được hướng dẫn tìm nguồn phù hợp.',student,'thẻ sinh viên mất thẻ bảo hiểm y tế điểm rèn luyện công tác sinh viên liên hệ phòng')
add('ky_tuc_xa','Đăng ký ký túc xá HaUI trực tuyến như thế nào?','Trung tâm Hỗ trợ sinh viên HaUI đã đăng “Hướng dẫn đăng ký phòng ở Ký túc xá trực tuyến dành cho tân sinh viên năm học 2026–2027”. Bạn mở hướng dẫn chính thức bên dưới và đối chiếu đúng đối tượng, cơ sở và thời gian tiếp nhận. Mình chưa thể kiểm tra phòng trống hoặc xác nhận bạn đã được bố trí chỗ ở.',housing,'đăng ký ký túc xá ktx phòng ở chỗ ở nội trú đăng ký online tân sinh viên',valid='2027-08-31')
add('ky_tuc_xa','Giá phòng và phí ký túc xá năm 2026–2027 xem ở đâu?','Trung tâm Hỗ trợ sinh viên HaUI có bài “Bảng giá phòng ở Ký túc xá năm học 2026–2027”. Giá cần đối chiếu theo cơ sở và loại phòng trong bảng chính thức. Mình chưa có dữ liệu để tính chi phí cá nhân hoặc khẳng định còn chỗ. Bạn muốn tìm cơ sở và loại phòng nào?',housing_price,'giá phòng tiền phòng phí ký túc xá bao nhiêu điện nước chi phí ở',valid='2027-08-31')
add('ky_tuc_xa','Lịch đăng ký ký túc xá dành cho tân sinh viên ở đâu?','Trường có thông báo “Lịch đăng ký Ký túc xá dành cho tân sinh viên năm học 2026–2027”. Bạn cần đọc ngày tiếp nhận và đối tượng trong thông báo; thông báo đã công bố không đồng nghĩa hiện vẫn đang mở đăng ký. Để hỏi đợt bổ sung hoặc phòng trống, liên hệ Trung tâm Hỗ trợ sinh viên.',housing_dates,'lịch đăng ký ký túc xá hạn đăng ký thời gian mở đăng ký bổ sung ktx',valid='2027-08-31')
add('ky_tuc_xa','Chưa nhận được tin nhắn nhận phòng ký túc xá cơ sở 3 thì sao?','Theo thông báo ngày 22/08/2026 của Trung tâm Ký túc xá, sự cố SMS không ảnh hưởng việc tiếp nhận sinh viên đã được bố trí chỗ ở tại cơ sở 3 theo kế hoạch của thông báo. Đây là thông tin của đợt tiếp nhận được nêu trong bài, không xác nhận tình trạng hiện tại của bạn. Bạn nên liên hệ Trung tâm để kiểm tra trường hợp cụ thể.',src('69590'),'sms nhận phòng tin nhắn cơ sở 3 ninh bình ký túc xá',kind='notice',valid='2027-08-31')
